import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

class TransactionErrorHandlingFixtureCleanupTest {
	@Test
	void failedTransactionCloseStillDeregistersAndRestoresConfiguration() {
		List<String> closed = new ArrayList<>();
		Exception failure = new Exception("transaction close");
		var cleanup = new TestTransactionControllerErrorHandling.TransactionCleanup();
		cleanup.transaction = () -> {
			throw failure;
		};
		cleanup.registration = () -> closed.add("registration");
		cleanup.configuration = () -> closed.add("configuration");
		assertSame(failure, assertThrows(Exception.class, cleanup::close));
		assertEquals(List.of("registration", "configuration"), closed);
	}

	@Test
	void failedDeregistrationStillRestoresConfiguration() throws Exception {
		Exception failure = new Exception("deregister");
		AutoCloseable configuration = mock(AutoCloseable.class);
		var cleanup = new TestTransactionControllerErrorHandling.TransactionCleanup();
		cleanup.transaction = () -> {
		};
		cleanup.registration = () -> {
			throw failure;
		};
		cleanup.configuration = configuration;
		assertSame(failure, assertThrows(Exception.class, cleanup::close));
		verify(configuration).close();
	}

	@Test
	void bodyFailureRemainsPrimaryWhenCleanupFails() {
		Exception body = new Exception("body");
		Exception close = new Exception("close");
		Exception restore = new Exception("restore");
		Exception actual = assertThrows(Exception.class, () -> {
			try (var cleanup = new TestTransactionControllerErrorHandling.TransactionCleanup()) {
				cleanup.transaction = () -> {
					throw close;
				};
				cleanup.configuration = () -> {
					throw restore;
				};
				throw body;
			}
		});
		assertSame(body, actual);
		assertSame(close, actual.getSuppressed()[0]);
		assertSame(restore, close.getSuppressed()[0]);
	}

	@Test
	void configurationRestoresWhenTransactionAcquisitionFails() throws Exception {
		AutoCloseable configuration = mock(AutoCloseable.class);
		Exception failure = new Exception("acquisition");
		assertSame(failure, assertThrows(Exception.class, () -> {
			try (var cleanup = new TestTransactionControllerErrorHandling.TransactionCleanup()) {
				cleanup.configuration = configuration;
				throw failure;
			}
		}));
		verify(configuration).close();
	}

}
